import { Hono } from 'hono'
import { ID, Query } from 'appwrite'
import { getDatabases, appwrite } from '../lib/appwrite'
import { authMiddleware } from '../middleware/auth'

type User = { id: string; email: string; name: string }
type Env = { Bindings: any; Variables: { user: User; env: any } }

const tasks = new Hono<Env>().basePath('/api/tasks').use('*', authMiddleware)

tasks.get('/', async (c) => {
  const e = c.get('env')
  const res = await getDatabases(e).listDocuments(
    e.appwriteDatabaseId, e.appwriteCollectionTasks,
    [Query.equal('userId', c.get('user').id), Query.orderDesc('createdAt')],
  )
  return c.json({ success: true, data: res.documents, error: null, meta: null })
})

tasks.post('/', async (c) => {
  const e = c.get('env')
  const { name }: any = await c.req.json().catch(() => ({}))
  if (!name || name.length < 1) return c.json({ success: false, data: null, error: { code: 'VALIDATION_ERROR', message: 'Task name required' }, meta: null }, 422)
  const doc = await getDatabases(e).createDocument(
    e.appwriteDatabaseId, e.appwriteCollectionTasks, ID.unique(),
    { userId: c.get('user').id, name, createdAt: new Date().toISOString() },
  )
  return c.json({ success: true, data: doc, error: null, meta: null }, 201)
})

tasks.delete('/:id', async (c) => {
  const e = c.get('env')
  try {
    const doc: any = await getDatabases(e).getDocument(e.appwriteDatabaseId, e.appwriteCollectionTasks, c.req.param('id'))
    if (doc.userId !== c.get('user').id) return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Task not found' }, meta: null }, 404)
    await getDatabases(e).deleteDocument(e.appwriteDatabaseId, e.appwriteCollectionTasks, c.req.param('id'))
    return c.json({ success: true, data: null, error: null, meta: null })
  } catch {
    return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Task not found' }, meta: null }, 404)
  }
})

export default tasks
