import { Hono } from 'hono'
import { ID, Query } from 'appwrite'
import { getDatabases, getProfile } from '../lib/appwrite'
import { authMiddleware } from '../middleware/auth'

type User = { id: string; email: string; name: string }
type Env = { Bindings: any; Variables: { user: User; env: any } }

const sessions = new Hono<Env>().basePath('/api/sessions').use('*', authMiddleware)

sessions.get('/active', async (c) => {
  const e = c.get('env')
  const res = await getDatabases(e).listDocuments(
    e.appwriteDatabaseId, e.appwriteCollectionSessions,
    [Query.equal('userId', c.get('user').id), Query.equal('status', 'active'), Query.limit(1)],
  )
  return c.json({ success: true, data: res.documents[0] ?? null, error: null, meta: null })
})

sessions.get('/', async (c) => {
  const e = c.get('env')
  const url = new URL(c.req.url)
  const page = Math.max(1, parseInt(url.searchParams.get('page') ?? '1'))
  const limit = Math.min(100, Math.max(1, parseInt(url.searchParams.get('limit') ?? '20')))
  const offset = (page - 1) * limit
  const filters: string[] = [Query.equal('userId', c.get('user').id)]
  const taskId = url.searchParams.get('taskId')
  if (taskId) filters.push(Query.equal('taskId', taskId))
  const from = url.searchParams.get('from')
  if (from) filters.push(Query.greaterThanEqual('startedAt', new Date(from).toISOString()))
  const to = url.searchParams.get('to')
  if (to) filters.push(Query.lessThanEqual('startedAt', new Date(to).toISOString()))
  filters.push(Query.orderDesc('startedAt'), Query.limit(limit), Query.offset(offset))
  const res = await getDatabases(e).listDocuments(e.appwriteDatabaseId, e.appwriteCollectionSessions, filters, undefined, true)
  return c.json({
    success: true, data: res.documents, error: null, meta: { page, limit, total: res.total, totalPages: Math.ceil(res.total / limit) },
  })
})

sessions.get('/:id', async (c) => {
  const e = c.get('env')
  try {
    const doc: any = await getDatabases(e).getDocument(e.appwriteDatabaseId, e.appwriteCollectionSessions, c.req.param('id'))
    if (doc.userId !== c.get('user').id) return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
    const events = await getDatabases(e).listDocuments(
      e.appwriteDatabaseId, e.appwriteCollectionEvents,
      [Query.equal('sessionId', doc.$id), Query.orderAsc('timestamp')],
    )
    return c.json({ success: true, data: { ...doc, events: events.documents }, error: null, meta: null })
  } catch {
    return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
  }
})

sessions.post('/', async (c) => {
  const e = c.get('env')
  const databases = getDatabases(e)
  const existing = await databases.listDocuments(
    e.appwriteDatabaseId, e.appwriteCollectionSessions,
    [Query.equal('userId', c.get('user').id), Query.equal('status', 'active'), Query.limit(1)],
  )
  if (existing.total > 0) return c.json({ success: false, data: null, error: { code: 'CONFLICT', message: 'Already have an active session' }, meta: null }, 409)
  const { taskId }: any = await c.req.json().catch(() => ({}))
  const now = new Date().toISOString()
  const doc = await databases.createDocument(
    e.appwriteDatabaseId, e.appwriteCollectionSessions, ID.unique(),
    { userId: c.get('user').id, taskId: taskId ?? null, status: 'active', durationSeconds: 0, restEarnedSeconds: 0, restTakenSeconds: 0, startedAt: now, createdAt: now },
  )
  await databases.createDocument(
    e.appwriteDatabaseId, e.appwriteCollectionEvents, ID.unique(),
    { sessionId: doc.$id, eventType: 'focus_started', timestamp: now, payload: '{}' },
  ).catch(() => {})
  return c.json({ success: true, data: doc, error: null, meta: null }, 201)
})

sessions.patch('/:id', async (c) => {
  const e = c.get('env')
  const databases = getDatabases(e)
  let doc: any
  try {
    doc = await databases.getDocument(e.appwriteDatabaseId, e.appwriteCollectionSessions, c.req.param('id'))
    if (doc.userId !== c.get('user').id) return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
  } catch {
    return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
  }
  const b: any = await c.req.json().catch(() => ({}))
  const updates: any = {}
  if (b.status) updates.status = b.status
  if (b.durationSeconds !== undefined) updates.durationSeconds = b.durationSeconds
  if (b.restEarnedSeconds !== undefined) updates.restEarnedSeconds = b.restEarnedSeconds
  if (b.restTakenSeconds !== undefined) updates.restTakenSeconds = b.restTakenSeconds
  if (b.endedAt) updates.endedAt = new Date(b.endedAt).toISOString()
  else if (b.status === 'completed' && !doc.endedAt) updates.endedAt = new Date().toISOString()
  if (b.status === 'completed' && b.durationSeconds !== undefined) {
    const profile = await getProfile(e, c.get('user').id)
    const ratio = profile?.restRatio ?? Number(e.restRatioDefault)
    updates.restEarnedSeconds = Math.floor(b.durationSeconds / ratio)
  }
  const updated = await databases.updateDocument(e.appwriteDatabaseId, e.appwriteCollectionSessions, c.req.param('id'), updates)
  if (b.status) {
    await databases.createDocument(
      e.appwriteDatabaseId, e.appwriteCollectionEvents, ID.unique(),
      { sessionId: updated.$id, eventType: b.status === 'completed' ? 'session_ended' : b.status, timestamp: new Date().toISOString(), payload: '{}' },
    ).catch(() => {})
  }
  return c.json({ success: true, data: updated, error: null, meta: null })
})

sessions.delete('/:id', async (c) => {
  const e = c.get('env')
  try {
    const doc: any = await getDatabases(e).getDocument(e.appwriteDatabaseId, e.appwriteCollectionSessions, c.req.param('id'))
    if (doc.userId !== c.get('user').id) return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
    await getDatabases(e).deleteDocument(e.appwriteDatabaseId, e.appwriteCollectionSessions, c.req.param('id'))
    return c.json({ success: true, data: null, error: null, meta: null })
  } catch {
    return c.json({ success: false, data: null, error: { code: 'NOT_FOUND', message: 'Session not found' }, meta: null }, 404)
  }
})

export default sessions
