import { Hono } from 'hono'
import { getEnvFromContext } from '../lib/env'
import { getDatabases } from '../lib/appwrite'
import { Query } from 'appwrite'

const debug = new Hono<{ Bindings: any; Variables: { env: any } }>()

debug.get('/env', (c) => {
  const e = c.get('env')
  return c.json({
    project_id: e.appwriteProjectId?.slice(0, 8) + '...',
    api_key_len: e.appwriteApiKey?.length ?? 0,
    endpoint: e.appwriteEndpoint,
    db_id: e.appwriteDatabaseId,
    node_env: e.nodeEnv,
  })
})

debug.post('/login-test', async (c) => {
  const e = c.get('env')
  const { email, password }: any = await c.req.json().catch(() => ({}))
  
  try {
    // Test 1: Direct fetch to session endpoint
    const res1 = await fetch(`${e.appwriteEndpoint}/account/sessions/email`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-appwrite-project': e.appwriteProjectId },
      body: JSON.stringify({ email, password }),
    })
    const text1 = await res1.text()
    
    // Test 2: Profile lookup via SDK
    const databases = getDatabases(e)
    const profiles = await databases.listDocuments(
      e.appwriteDatabaseId, e.appwriteCollectionProfiles,
      [Query.equal('email', email)],
    )
    
    return c.json({ 
      login_status: res1.status, 
      login_body: text1.slice(0, 300),
      profile_count: profiles.total,
      profile_ids: profiles.documents.map((d: any) => d.$id),
    })
  } catch (err: any) {
    return c.json({ error: err?.message ?? String(err), stack: err?.stack?.slice(0, 500) }, 500)
  }
})

export default debug
