import { Client, Databases, Storage, Account, ID, Query } from 'appwrite'

export type EnvVars = {
  appwriteEndpoint: string
  appwriteProjectId: string
  appwriteApiKey: string
  appwriteDatabaseId: string
  appwriteCollectionProfiles: string
  appwriteCollectionTasks: string
  appwriteCollectionSessions: string
  appwriteCollectionEvents: string
  appwriteBucketAvatars: string
}

export function getAdminClient(e: EnvVars) {
  return new Client().setEndpoint(e.appwriteEndpoint).setProject(e.appwriteProjectId).setDevKey(e.appwriteApiKey)
}

export function getSessionClient(e: EnvVars, sessionSecret: string) {
  const c = new Client().setEndpoint(e.appwriteEndpoint).setProject(e.appwriteProjectId)
  if (sessionSecret) c.setSession(sessionSecret)
  return c
}

export function getPublicClient(e: EnvVars) {
  return new Client().setEndpoint(e.appwriteEndpoint).setProject(e.appwriteProjectId)
}

export function getDatabases(e: EnvVars) { return new Databases(getAdminClient(e)) }
export function getStorage(e: EnvVars)   { return new Storage(getAdminClient(e)) }
export function getAccount(e: EnvVars)   { return new Account(getPublicClient(e)) }

export async function getProfile(e: EnvVars, userId: string) {
  const res = await getDatabases(e).listDocuments(
    e.appwriteDatabaseId, e.appwriteCollectionProfiles,
    [Query.equal('userId', userId)],
  )
  return res.documents[0] ?? null
}

// Backward compat object
export const appwrite = {
  databaseId: 'flowdoro',
  collections: {
    profiles: 'profiles',
    tasks: 'tasks',
    sessions: 'sessions',
    events: 'session_events',
  },
  buckets: {
    avatars: 'avatars',
  },
}

export { ID, Query }
