import { Hono } from 'hono'
import { ID, Query } from 'appwrite'
import { getDatabases, appwrite } from '../lib/appwrite'
import { json, setSessionCookie, clearSessionCookie } from '../lib/response'

type User = { id: string; email: string; name: string }
type Env = { Bindings: any; Variables: { user: User; env: any } }

function serializeProfile(doc: any) {
  if (!doc) return null
  return {
    id: doc.$id, userId: doc.userId, email: doc.email, name: doc.name,
    avatarUrl: doc.avatarUrl ?? null, restRatio: doc.restRatio ?? 5,
    theme: doc.theme ?? 'system', notificationsEnabled: doc.notificationsEnabled ?? false,
    soundEnabled: doc.soundEnabled ?? false, createdAt: doc.createdAt, updatedAt: doc.updatedAt,
  }
}

const auth = new Hono<Env>()

auth.post('/register', async (c) => {
  const { name, email, password }: any = await c.req.json().catch(() => ({}))
  if (!name || name.length < 2) return json({ success: false, data: null, error: { code: 'VALIDATION_ERROR', message: 'Name min 2 chars' }, meta: null }, 422)
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({ success: false, data: null, error: { code: 'VALIDATION_ERROR', message: 'Invalid email' }, meta: null }, 422)
  if (!password || password.length < 8) return json({ success: false, data: null, error: { code: 'VALIDATION_ERROR', message: 'Password min 8 chars' }, meta: null }, 422)

  const emailLower = email.toLowerCase()
  const e = c.get('env')
  try {
    const createRes = await fetch(`${e.appwriteEndpoint}/users`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-appwrite-project': e.appwriteProjectId, 'x-appwrite-key': e.appwriteApiKey },
      body: JSON.stringify({ userId: ID.unique(), email: emailLower, password, name }),
    })
    if (!createRes.ok) {
      const errBody: any = await createRes.json().catch(() => ({}))
      if (/already|exists/i.test(errBody?.message ?? '')) return json({ success: false, data: null, error: { code: 'CONFLICT', message: 'Email already registered' }, meta: null }, 409)
      throw new Error(errBody?.message ?? 'Registration failed')
    }
    const user: any = await createRes.json()

    // Create profile via SDK
    const databases = getDatabases(e)
    await databases.createDocument(e.appwriteDatabaseId, e.appwriteCollectionProfiles, ID.unique(), {
      userId: user.$id, email: emailLower, name, restRatio: 5, theme: 'system',
      notificationsEnabled: false, soundEnabled: false,
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
    }).catch((err: any) => console.error('profile create failed', err?.message))

    // Login to create session
    const loginRes = await fetch(`${e.appwriteEndpoint}/account/sessions/email`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-appwrite-project': e.appwriteProjectId },
      body: JSON.stringify({ email: emailLower, password }),
    })
    if (!loginRes.ok) throw new Error('Login failed after registration')
    const session: any = await loginRes.json()
    const setHeaders = new Headers()
    setSessionCookie(setHeaders, session.secret ?? '')
    return c.json({
      success: true,
      data: serializeProfile({ $id: user.$id, userId: user.$id, email: emailLower, name, avatarUrl: null, restRatio: 5, theme: 'system', notificationsEnabled: false, soundEnabled: false }),
      error: null, meta: null,
    }, 201, Object.fromEntries(setHeaders.entries()))
  } catch (e: any) {
    console.error('register failed', e.message)
    return json({ success: false, data: null, error: { code: 'INTERNAL_ERROR', message: e?.message ?? 'Registration failed' }, meta: null }, 500)
  }
})

auth.post('/login', async (c) => {
  const { email, password }: any = await c.req.json().catch(() => ({}))
  if (!email || !password) return json({ success: false, data: null, error: { code: 'VALIDATION_ERROR', message: 'Email and password required' }, meta: null }, 422)
  const emailLower = email.toLowerCase()
  const e = c.get('env')
  try {
    const loginRes = await fetch(`${e.appwriteEndpoint}/account/sessions/email`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-appwrite-project': e.appwriteProjectId },
      body: JSON.stringify({ email: emailLower, password }),
    })
    if (!loginRes.ok) throw new Error('Invalid credentials')
    const session: any = await loginRes.json()
    const setHeaders = new Headers()
    setSessionCookie(setHeaders, session.secret ?? '')

    // Fetch profile via SDK
    const databases = getDatabases(e)
    const profiles = await databases.listDocuments(
      e.appwriteDatabaseId, e.appwriteCollectionProfiles,
      [Query.equal('email', emailLower)],
    )
    return c.json({
      success: true, data: serializeProfile(profiles.documents?.[0] ?? null), error: null, meta: null,
    }, 200, Object.fromEntries(setHeaders.entries()))
  } catch {
    return json({ success: false, data: null, error: { code: 'UNAUTHORIZED', message: 'Invalid email or password' }, meta: null }, 401)
  }
})

auth.post('/logout', async (c) => {
  const setHeaders = new Headers()
  clearSessionCookie(setHeaders)
  return c.json({ success: true, data: null, error: null, meta: null }, 200, Object.fromEntries(setHeaders.entries()))
})

export default auth
