const SESSION_COOKIE = 'token'

export function json(data: unknown, status = 200, extraHeaders?: Record<string, string>) {
  const h = new Headers({ 'content-type': 'application/json', ...extraHeaders })
  return new Response(JSON.stringify(data), { status, headers: h })
}

export function setSessionCookie(resHeaders: Headers, token: string) {
  resHeaders.set(
    'Set-Cookie',
    `${SESSION_COOKIE}=${token}; Path=/; Max-Age=${7 * 24 * 3600}; SameSite=Lax; ${process.env.NODE_ENV === 'production' ? 'Secure' : ''}`,
  )
}

export function clearSessionCookie(resHeaders: Headers) {
  resHeaders.set('Set-Cookie', `${SESSION_COOKIE}=; Path=/; Max-Age=0; SameSite=Lax`)
}

export function getSessionToken(req: Request): string {
  const cookieHeader = req.headers.get('cookie') ?? ''
  const match = cookieHeader.match(new RegExp(`(?:^|; )${SESSION_COOKIE}=(.*?)$`))
  if (match?.[1]) return match[1]
  const auth = req.headers.get('authorization') ?? ''
  return auth.startsWith('Bearer ') ? auth.slice(7) : ''
}
